<?php
declare(strict_types=1);use Acorn\SafetyHealthcheck\Reports\PdfGenerator;
final class PdfGeneratorTest extends IntegrationTestCase{public function test_pdf_contains_real_pdf_signature():void{$data=['meta'=>['company'=>'Test','assessment_date'=>'2026-09-17'],'summary'=>['priority_count'=>0,'review_count'=>0,'addressed_count'=>0],'pillars'=>[],'sections'=>['addressed'=>['label'=>'Working'],'review'=>['label'=>'Review'],'priority'=>['label'=>'Priority']],'addressed'=>[],'review'=>[],'priority'=>[],'action_summary'=>[],'disclaimer'=>'Indicative only.','support'=>['heading'=>'Help']];$path=(new PdfGenerator)->toTempFile($data);self::assertSame('%PDF',file_get_contents($path,false,null,0,4));self::assertGreaterThan(1000,filesize($path));unlink($path);}}
